429	                <input data-testid="claim-reject-reason" placeholder="Reason" value={reasons[c.id] ?? ''}
430	                  onChange={(e) => {
431	                    setReasons((r) => ({ ...r, [c.id]: e.target.value }));
432	                    if (move.variables?.id === c.id) move.reset();
433	                  }} />{' '}
434	                <button type="button" data-testid="claim-reject" disabled={move.isPending}
435	                  onClick={() => act(c.id, 'reject')}>
436	                  {LABELS.reject}
437	                </button>{' '}
438	                <input type="date" data-testid="claim-defer-date" value={deferDates[c.id] ?? ''}
439	                  onChange={(e) => {
440	                    setDeferDates((d) => ({ ...d, [c.id]: e.target.value }));
441	                    if (deferral.variables?.id === c.id) deferral.reset();
442	                  }} />{' '}
443	                <button type="button" data-testid="claim-defer" disabled={deferral.isPending}
444	                  onClick={() => defer(c.id)}>
445	                  Defer
446	                </button>{' '}
447	                <input type="date" data-testid="claim-date-new" value={redates[c.id] ?? ''}
448	                  onChange={(e) => {
449	                    setRedates((d) => ({ ...d, [c.id]: e.target.value }));
450	                    if (redating.variables?.id === c.id) redating.reset();
451	                  }} />{' '}
452	                <button type="button" data-testid="claim-redate" disabled={redating.isPending}
453	                  onClick={() => redate(c.id)}>
454	                  Re-date
455	                </button>{' '}
456	                <select data-testid="claim-reassign-to" value={targets[c.id] ?? String(others[0]?.id ?? '')}
457	                  onChange={(e) => {
458	                    setTargets((t) => ({ ...t, [c.id]: e.target.value }));
459	                    if (reassign.variables?.id === c.id) reassign.reset();
460	                  }}>
461	                  {others.map((p) => <option key={p.id} value={String(p.id)}>{p.name}</option>)}
462	                </select>{' '}
463	                <button type="button" data-testid="claim-reassign" disabled={reassign.isPending || others.length === 0}
464	                  onClick={() => moveTo(c.id)}>
465	                  Reassign
466	                </button>{' '}
467	                <button type="button" data-testid="claim-edit" onClick={() => open(c)}>
468	                  Edit
469	                </button>
470	                {editing === c.id && (
471	                  <button type="button" data-testid="claim-cancel" onClick={cancel}>
472	                    Cancel
473	                  </button>
474	                )}
475	                {editRefused?.id === c.id && (
476	                  <span data-testid="claim-error">{editRefused.message}</span>
477	                )}
478	                {locking.isError && locking.variables === c.id && (
479	                  <span data-testid="claim-error">{locking.error instanceof HttpError && locking.error.status === 412
480	                    ? 'Another user is editing this claim; it cannot be edited until they save or cancel.'
481	                    : locking.error instanceof HttpError && locking.error.status === 423
482	                    ? 'A claim due by a day inside a closed period cannot be edited.'
483	                    : locking.error instanceof HttpError && locking.error.status === 409
484	                    ? `A ${c.status} claim cannot be edited. To change it, void it and add a new one.`
485	                    : 'Your role may not edit a claim.'}</span>
486	                )}
487	                {move.isError && move.variables?.id === c.id && (
488	                  <span data-testid="claim-error">{move.error instanceof HttpError && move.error.status === 423
489	                    ? 'A claim due by a day inside a closed period cannot be changed.'
490	                    : move.error instanceof HttpError && move.error.status === 400
491	                    ? 'A rejection needs a reason.'
492	                    : (move.variables.action === 'settle' || move.variables.action === 'approve') && needsProof(c)
493	                    ? 'A claim whose due is above the proof threshold needs a proof first.'
494	                    : move.variables.action === 'open' && c.status === 'DRAFT' && needsNote(c)
495	                    ? 'A claim whose due is above the note threshold needs a note before it is opened.'
496	                    : c.deferred && move.variables.action === 'settle'
497	                    ? `A deferred claim cannot be settled until ${c.deferredUntil}.`
498	                    : c.status === 'OPEN' && move.variables.action === 'settle'
499	                    ? 'The user who opened a claim cannot settle it, nor can a role the permissions do not allow to settle.'
500	                    : c.status === 'PENDING' && move.variables.action === 'approve'
501	                    ? 'Only a steward who did not open a claim can approve it.'
502	                    : c.status === 'PENDING' && move.variables.action === 'reject'
503	                    ? 'Only a steward can reject a claim.'
504	                    : c.status === 'SETTLED' && move.variables.action === 'resettle'
505	                    ? 'Only a steward can re-settle a claim.'
506	                    : `A ${c.status} claim cannot be ${DONE[move.variables.action]}, or your role may not ${move.variables.action} a claim.`}</span>
507	                )}
508	                {deferral.isError && deferral.variables?.id === c.id && (
509	                  <span data-testid="claim-error">{deferral.error instanceof HttpError && deferral.error.status === 423
510	                    ? 'A claim due by a day inside a closed period cannot be deferred.'
511	                    : deferral.error instanceof HttpError && deferral.error.status === 400
512	                    ? 'A claim can only be deferred to a date after the sheet\'s today.'
513	                    : `A ${c.status} claim cannot be deferred.`}</span>
514	                )}
515	                {reminder.isError && reminder.variables === c.id && (
516	                  <span data-testid="claim-error">{reminder.error instanceof HttpError && reminder.error.status === 409
517	                    ? (c.status === 'OPEN' || c.status === 'PENDING'
518	                      ? `The claim was already reminded on ${c.reminded ?? today}.`
519	                      : `A ${c.status} claim cannot be reminded.`)
520	                    : 'Your role may not remind a claim.'}</span>
521	                )}
522	                {redating.isError && redating.variables?.id === c.id && (
523	                  <span data-testid="claim-error">{redating.error instanceof HttpError && redating.error.status === 423
524	                    ? 'A claim due by a day inside a closed period cannot be re-dated.'
525	                    : redating.error instanceof HttpError && redating.error.status === 400
526	                    ? 'A claim needs a date on or before its person\'s retirement.'
527	                    : c.status === 'OPEN' || c.status === 'PENDING'
528	                    ? 'Only a steward can re-date a claim.'
529	                    : `A ${c.status} claim cannot be re-dated.`}</span>
530	                )}
531	                {division.isError && division.variables?.id === c.id && (
532	                  <span data-testid="claim-error">{division.error instanceof HttpError && division.error.status === 423
533	                    ? 'A claim due by a day inside a closed period cannot be split.'
534	                    : division.error instanceof HttpError && division.error.status === 400
535	                    ? `A split needs an amount more than 0.00 and less than ${Number(c.amount).toFixed(2)}.`
536	                    : c.status === 'OPEN' && !c.deferred
537	                    ? 'Your role may not open a claim, so it cannot split one.'
538	                    : `A ${c.deferred ? 'deferred' : c.status} claim cannot be split.`}</span>
539	                )}
540	                {proof.isError && proof.variables === c.id && (
541	                  <span data-testid="claim-error">{proof.error instanceof HttpError && proof.error.status === 423
542	                    ? 'A claim due by a day inside a closed period cannot gain a proof.'
543	                    : `A ${c.status} claim cannot gain a proof.`}</span>
544	                )}
545	                {reassign.isError && reassign.variables?.id === c.id && (
546	                  <span data-testid="claim-error">{reassign.error instanceof HttpError && reassign.error.status === 423
547	                    ? 'A claim due by a day inside a closed period cannot be reassigned.'
548	                    : c.status === 'SETTLED' || c.status === 'VOID'
549	                    ? `A ${c.status} claim cannot be reassigned.`
550	                    : 'Only a role the permissions allow can reassign a claim, and only to another person.'}</span>
551	                )}
552	              </td>
553	            </tr>
554	          ))}
555	        </tbody>
556	      </table>
557	    </div>
558	  );
559	}

